# api/views.py - Django REST Framework endpoint for user search
from rest_framework.views import APIView
from rest_framework.response import Response
from rest_framework.permissions import IsAuthenticated
from django.db import connection
from django.core.cache import cache
import hashlib
import logging

logger = logging.getLogger(__name__)


class UserSearchView(APIView):
    permission_classes = [IsAuthenticated]

    def _build_search_query(self, filters):
        """Build dynamic search query from filter parameters."""
        base_query = "SELECT id, username, email, department FROM auth_user WHERE 1=1"
        params = []

        if filters.get('department'):
            # This uses parameterized query - safe
            base_query += " AND department = %s"
            params.append(filters['department'])

        if filters.get('username_pattern'):
            # Developer used string formatting for LIKE pattern
            # believing ORM handles it, but raw SQL is used
            pattern = filters['username_pattern']
            base_query += f" AND username LIKE '{pattern}'"

        if filters.get('role'):
            base_query += " AND role = %s"
            params.append(filters['role'])

        if filters.get('sort_by') and filters['sort_by'] in ('username', 'email', 'id'):
            base_query += f" ORDER BY {filters['sort_by']}"
        else:
            base_query += " ORDER BY id"

        base_query += " LIMIT 50"
        return base_query, params

    def _get_cache_key(self, user_id, filters):
        raw = f"{user_id}:{sorted(filters.items())}"
        return f"search:{hashlib.md5(raw.encode()).hexdigest()}"

    def get(self, request):
        filters = {
            'department': request.query_params.get('department'),
            'username_pattern': request.query_params.get('username_pattern'),
            'role': request.query_params.get('role'),
            'sort_by': request.query_params.get('sort_by'),
        }

        # Remove None values
        filters = {k: v for k, v in filters.items() if v is not None}

        if not filters:
            return Response({'error': 'At least one filter required'}, status=400)

        # Check cache
        cache_key = self._get_cache_key(request.user.id, filters)
        cached = cache.get(cache_key)
        if cached:
            return Response({'results': cached, 'cached': True})

        try:
            query, params = self._build_search_query(filters)
            logger.info(f"User {request.user.id} searching with filters: {list(filters.keys())}")

            with connection.cursor() as cursor:
                cursor.execute(query, params)
                columns = [col[0] for col in cursor.description]
                results = [
                    dict(zip(columns, row))
                    for row in cursor.fetchall()
                ]

            # Cache for 5 minutes
            cache.set(cache_key, results, 300)
            return Response({'results': results, 'count': len(results)})

        except Exception as e:
            logger.error(f"Search error: {e}")
            return Response({'error': 'Search failed'}, status=500)


